B.at6=s(["Dorada \u2192 lubina, pargo o 2 lomos de merluza (10 minutos)."],t.s)
B.b85=new A.W("\xbfC\xf3mo la sirvo sin espinas?","Abre por el lomo con un cuchillo, levanta la carne de arriba, quita la espina central de una pieza y ya tienes la de abajo limpia.")
B.aBW=s([B.b85],t.Wy)
B.b3s=new A.av(B.c1,B.asN,"P\xeddele al pescadero que te la limpie y quite las escamas. Horno a 200 \xb0C.","El ojo se pone blanco y la carne se separa f\xe1cil de la espina central (unos 15-18 minutos para una dorada de 400 g).",B.auT,B.aqc,B.at6,"Mejor reci\xe9n hecha.",null,B.aBW)
B.aOm=s(["Bol","Escurridor","T\xe1per"],t.s)
